  position: relative;

  &:last-child {
    margin-bottom: 0;
  }

  &::before {
    content: '';
    position: absolute;
    width: 12px;
    height: 12px;
    background-color: #fff;
    border: 2px solid #444;
    border-radius: 50%;
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1;
  }
`;

const TimelineContent = styled.div`
  background-color: #222;
  padding: 15px;
  border-radius: 8px;
  width: 45%;
  margin-left: ${props => props.align === 'left' ? '0' : '55%'};
  text-align: ${props => props.align === 'left' ? 'left' : 'right'};

  &::before {
    content: '';
    position: absolute;
    top: 15px;
    width: 0;
    height: 0;
    border-style: solid;
    border-width: 10px;
    border-color: transparent;
    z-index: 1;
    left: ${props => props.align === 'left' ? '45%' : 'auto'};
    right: ${props => props.align === 'left' ? 'auto' : '45%'};
    border-${props => props.align === 'left' ? 'right' : 'left'}-color: #222;
  }
`;

const TimelineTitle = styled.h3`
  font-size: 1.3em;
  margin-bottom: 5px;
`;

const TimelineSubtitle = styled.p`
  font-size: 1em;
  color: #aaa;
  margin-bottom: 10px;
`;

const TimelineDescription = styled.p`
  font-size: 1em;
  line-height: 1.4;
`;

function Experience() {
  return (
    <ExperienceSection>
      <h2>Experience</h2>
      <Timeline>
        {experience.map((item, index) => (
          <TimelineItem key={item.id}>
            <TimelineContent align={index % 2 === 0 ? 'left' : 'right'}>
              <TimelineTitle>{item.title}</TimelineTitle>
              <TimelineSubtitle>{item.company} - {item.dates}</TimelineSubtitle>
              <TimelineDescription>{item.description}</TimelineDescription>
            </TimelineContent>
          </TimelineItem>
        ))}
      </Timeline>
    </ExperienceSection>
  );
}

export default Experience;
